WITH UserPostStatistics AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(p.Id) AS TotalPosts, SUM(CASE WHEN p.PostTypeId = 1 THEN 1 ELSE 0 END) AS Questions, SUM(CASE WHEN p.PostTypeId = 2 THEN 1 ELSE 0 END) AS Answers, SUM(CASE WHEN p.LastActivityDate > (CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' MONTH) THEN 1 ELSE 0 END) AS RecentActivity FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId GROUP BY u.Id, u.DisplayName), RankedUsers AS (SELECT UserId, DisplayName, TotalPosts, Questions, Answers, RecentActivity, RANK() OVER (ORDER BY TotalPosts DESC NULLS FIRST) AS PostRank FROM UserPostStatistics), TopUsers AS (SELECT UserId, DisplayName, TotalPosts, Questions, Answers, RecentActivity FROM RankedUsers WHERE PostRank <= 10), CloseReasonStatistics AS (SELECT ph.UserId, COUNT(*) AS CloseReasonCount, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.UserId) SELECT tu.DisplayName, tu.TotalPosts, tu.Questions, tu.Answers, COALESCE(cr.CloseReasonCount, 0) AS CloseReasonCount, COALESCE(cr.CloseReasons, 'None') AS CloseReasons, CASE WHEN tu.RecentActivity > 0 THEN 'Active' ELSE 'Inactive' END AS ActivityStatus FROM TopUsers AS tu LEFT JOIN CloseReasonStatistics AS cr ON tu.UserId = cr.UserId ORDER BY tu.TotalPosts DESC NULLS FIRST